INSERT INTO feature VALUES('function-extensionality','identity','Function extensionality by computation',NULL,'partial','notable',NULL,'`Path.funext(f, g)` is decided by evaluating both functions over their finite inputs, a data type covered as its constructors over their fields, and replayed by the kernel, open functions and a type holding itself refused by name; at the empty row it is also derived from `ua` for functions, a returned call read as the call it holds.','core-checker core-nbe kernel-core surface-diagnostics','corpus/model/identity/funext.gandr corpus/model/identity/funext-higher.gandr corpus/model/identity/funext-from-ua.gandr corpus/model/identity/funext-data.gandr corpus/pathological/identity/open-function-funext.gandr corpus/pathological/identity/funext-data.gandr','corpus/ledger/features/function-extensionality.gandr','#312');
